file.required-changes:
// After line 70 (after cachedConfig is populated), add validation warning:

// Story 8.4: Warn about potential missing auth for Cloud Run servers
for (const [name, serverConfig] of Object.entries(cachedConfig)) {
  const httpConfig = serverConfig as { url?: string; headers?: Record<string, string>; authType?: string };
  if (
    httpConfig.url?.includes('.run.app') &&
    !httpConfig.headers?.Authorization &&
    !httpConfig.authType
  ) {
    logger.warn({
      event: 'mcp.config.possible_missing_auth',
      server: name,
      url: httpConfig.url,
      hint: 'Cloud Run servers typically require authType: gcp_identity',
    });
  }
}

// Add new describe block after existing tests:

describe('config validation warning (Story 8.4 AC6)', () => {
  it('logs warning for .run.app URL with empty headers and no authType (T2.1)', () => {
    clearMcpConfigCache();
    const mockYaml = `
mcp_servers:
  audience-manager:
    enabled: true
    type: http
    url: "https://audience-manager-mcp-vjlizxe2vq-uc.a.run.app/mcp"
    headers: {}
`;
    vi.mocked(readFileSync).mockReturnValue(mockYaml);

    loadMcpServersConfig('/test/path');

    expect(logger.warn).toHaveBeenCalledWith(
      expect.objectContaining({
        event: 'mcp.config.possible_missing_auth',
        server: 'audience-manager',
      })
    );
  });

  it('does not warn when authType: gcp_identity is configured (T2.2)', () => {
    clearMcpConfigCache();
    const mockYaml = `
mcp_servers:
  genmedia-imagen:
    enabled: true
    type: http
    url: "https://mcp-imagen-201626763325.us-central1.run.app/mcp"
    headers: {}
    authType: gcp_identity
`;
    vi.mocked(readFileSync).mockReturnValue(mockYaml);

    loadMcpServersConfig('/test/path');

    expect(logger.warn).not.toHaveBeenCalledWith(
      expect.objectContaining({
        event: 'mcp.config.possible_missing_auth',
      })
    );
  });

  it('does not warn when Authorization header is configured (T2.3)', () => {
    clearMcpConfigCache();
    const mockYaml = `
mcp_servers:
  rube:
    enabled: true
    type: http
    url: "https://some-cloud-run.a.run.app/mcp"
    headers:
      Authorization: "Bearer token123"
`;
    vi.mocked(readFileSync).mockReturnValue(mockYaml);

    loadMcpServersConfig('/test/path');

    expect(logger.warn).not.toHaveBeenCalledWith(
      expect.objectContaining({
        event: 'mcp.config.possible_missing_auth',
      })
    );
  });

  it('passes authType through to SDK config for http type (T2.4)', () => {
    clearMcpConfigCache();
    const mockYaml = `
mcp_servers:
  genmedia-imagen:
    enabled: true
    type: http
    url: "https://mcp-imagen.run.app/mcp"
    headers: {}
    authType: gcp_identity
`;
    vi.mocked(readFileSync).mockReturnValue(mockYaml);

    const config = loadMcpServersConfig('/test/path');

    expect(config['genmedia-imagen']).toMatchObject({
      type: 'http',
      authType: 'gcp_identity',
    });
  });
});

// Add new describe block for auth scenarios (Story 8.4):

// Add mock for gcp-auth module at top of file (after existing mocks):
vi.mock('./gcp-auth.js', () => ({
  getGcpIdentityToken: vi.fn(),
}));

import { getGcpIdentityToken } from './gcp-auth.js';

describe('getAuthHeader auth scenarios (Story 8.4)', () => {
  beforeEach(() => {
    vi.mocked(getGcpIdentityToken).mockReset();
  });

  it('returns GCP identity token when authType is gcp_identity (T1.1)', async () => {
    vi.mocked(getGcpIdentityToken).mockResolvedValue('mock-gcp-identity-token');

    setupMockWithInit({ jsonrpc: '2.0', id: 2, result: { tools: [] } });

    const client = new McpClient('test-server', {
      url: 'https://test.run.app/mcp',
      authType: 'gcp_identity',
    });

    await client.listTools();

    // Verify GCP identity token was fetched
    expect(getGcpIdentityToken).toHaveBeenCalledWith(
      'https://test.run.app',
      undefined
    );

    // Verify auth header was set
    const initCall = mockFetch.mock.calls.find(
      (call) => JSON.parse(call[1].body).method === 'initialize'
    );
    expect(initCall![1].headers['Authorization']).toBe('Bearer mock-gcp-identity-token');
  });

  it('returns undefined (no auth) when neither bearerToken nor authType configured (T1.2)', async () => {
    setupMockWithInit({ jsonrpc: '2.0', id: 2, result: { tools: [] } });

    const client = new McpClient('test-server', {
      url: 'https://mcp.example.com',
      // No bearerToken, no authType
    });

    await client.listTools();

    const initCall = mockFetch.mock.calls.find(
      (call) => JSON.parse(call[1].body).method === 'initialize'
    );
    expect(initCall![1].headers['Authorization']).toBeUndefined();
  });

  it('uses URL origin as audience for GCP identity token (T1.4)', async () => {
    vi.mocked(getGcpIdentityToken).mockResolvedValue('token');

    setupMockWithInit({ jsonrpc: '2.0', id: 2, result: { tools: [] } });

    const client = new McpClient('test-server', {
      url: 'https://audience-manager-mcp-vjlizxe2vq-uc.a.run.app/mcp',
      authType: 'gcp_identity',
    });

    await client.listTools();

    expect(getGcpIdentityToken).toHaveBeenCalledWith(
      'https://audience-manager-mcp-vjlizxe2vq-uc.a.run.app',
      undefined
    );
  });

  it('logs error and returns undefined when GCP identity fetch fails (T1.5)', async () => {
    vi.mocked(getGcpIdentityToken).mockRejectedValue(new Error('GCP auth failed'));

    mockFetch.mockImplementation((_url, opts) => {
      const body = JSON.parse(opts.body);
      // Initialize will succeed (no auth required for test mock)
      if (body.method === 'initialize') {
        return Promise.resolve(mockResponse({
          jsonrpc: '2.0',
          id: body.id,
          result: { protocolVersion: '2025-06-18', capabilities: {} },
        }));
      }
      if (body.method === 'notifications/initialized') {
        return Promise.resolve({ ok: true, status: 202, headers: { get: () => null }, text: () => Promise.resolve('') });
      }
      return Promise.resolve(mockResponse({ jsonrpc: '2.0', id: body.id, result: { tools: [] } }));
    });

    const client = new McpClient('test-server', {
      url: 'https://test.run.app/mcp',
      authType: 'gcp_identity',
    });

    await client.listTools();

    // Verify error was logged
    expect(logger.error).toHaveBeenCalledWith(
      expect.objectContaining({
        event: 'mcp.auth.gcp_identity_failed',
        serverName: 'test-server',
      })
    );
  });

  it('static bearer token takes precedence over authType gcp_identity (T1.6)', async () => {
    vi.mocked(getGcpIdentityToken).mockResolvedValue('should-not-use');

    setupMockWithInit({ jsonrpc: '2.0', id: 2, result: { tools: [] } });

    const client = new McpClient('test-server', {
      url: 'https://test.run.app/mcp',
      bearerToken: 'static-token',
      authType: 'gcp_identity', // Should be ignored
    });

    await client.listTools();

    // Should NOT call GCP identity token
    expect(getGcpIdentityToken).not.toHaveBeenCalled();

    // Should use static bearer token
    const initCall = mockFetch.mock.calls.find(
      (call) => JSON.parse(call[1].body).method === 'initialize'
    );
    expect(initCall![1].headers['Authorization']).toBe('Bearer static-token');
  });
});
